1	/**
2	 * The multi-tenancy invariant, exercised against a real database.
3	 *
4	 * Every repository read must be filtered by `org_id`. These cases create two
5	 * organizations with identical-looking content and then ask each one for the
6	 * other's rows: the answer has to be "nothing", at every level of the stack.
7	 */
8	import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
9	
10	vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
11	
12	import * as commentRepo from "@/server/repositories/comment-repository";
13	import * as issueRepo from "@/server/repositories/issue-repository";
14	import * as memberRepo from "@/server/repositories/member-repository";
15	import * as projectRepo from "@/server/repositories/project-repository";
16	import * as issueService from "@/server/services/issue-service";
17	import { TenantScopeError } from "@/lib/tenant";
18	import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
19	import type { Tenant } from "./_support/fixtures";
20	import type { Issue } from "@/types/issue";
21	
22	let cleanup: () => void;
23	let north: Tenant;
24	let acme: Tenant;
25	let northIssue: Issue;
26	
27	beforeAll(async () => {
28	  cleanup = await useTemporaryDatabase();
29	
30	  north = await createTenant("northwind");
31	  acme = await createTenant("acme");
32	
33	  northIssue = await issueService.createIssue(
34	    north.actors.member,
35	    issueInput(north.org.id, north.project.id, { title: "Northwind only" }),
36	  );
37	
38	  await issueService.createIssue(
39	    acme.actors.member,
40	    issueInput(acme.org.id, acme.project.id, { title: "Acme only" }),
41	  );
42	});
43	
44	afterAll(() => {
45	  cleanup();
